-- communities module's schema.ts). Additive only: no existing table changes.
--
--   communities              the aggregate root: status, lifecycle and membership
--                            versions, and a maintained member count (no upper bound)
--   community_members        one row per stint — one stay of one account in one
--                            community; a rejoin is a new row, history is kept
--   community_invitations    links: only the SHA-256 of each token is stored,
--                            and the state is derived, never stored
--
-- Account ids are not foreign keys (accounts are identity's); inside the module
-- every key is RESTRICT, because a community is never deleted (Q47).

CREATE TABLE "communities" (
	"id" text PRIMARY KEY NOT NULL,
	"title" text NOT NULL,
	"status" text NOT NULL,
	"lifecycle_version" integer DEFAULT 1 NOT NULL,
	"membership_version" bigint DEFAULT 0 NOT NULL,
	"member_count" integer DEFAULT 0 NOT NULL,
	"created_by" text,
	"created_at" timestamp with time zone NOT NULL,
	"status_changed_at" timestamp with time zone,
	"status_changed_by" text,
	"updated_at" timestamp with time zone NOT NULL,
	CONSTRAINT "communities_title_length" CHECK (char_length("communities"."title") between 1 and 100),
	CONSTRAINT "communities_status_valid" CHECK ("communities"."status" in ('OPEN', 'LOCKED')),
	CONSTRAINT "communities_lifecycle_version_positive" CHECK ("communities"."lifecycle_version" >= 1),
	CONSTRAINT "communities_membership_version_nonnegative" CHECK ("communities"."membership_version" >= 0),
	CONSTRAINT "communities_member_count_nonnegative" CHECK ("communities"."member_count" >= 0),
	CONSTRAINT "communities_updated_after_created" CHECK ("communities"."updated_at" >= "communities"."created_at")
);
