CREATE TABLE "community_invitations" (
	"id" text PRIMARY KEY NOT NULL,
	"community_id" text NOT NULL,
	"token_hash" text NOT NULL,
	"created_by" text NOT NULL,
	"created_at" timestamp with time zone NOT NULL,
	"expires_at" timestamp with time zone NOT NULL,
	"max_uses" integer,
	"uses" integer DEFAULT 0 NOT NULL,
	"revoked_at" timestamp with time zone,
	"revoked_by" text,
	CONSTRAINT "community_invitations_token_hash_unique" UNIQUE("token_hash"),
	CONSTRAINT "community_invitations_token_hash_shape" CHECK ("community_invitations"."token_hash" ~ '^[0-9a-f]{64}$'),
	CONSTRAINT "community_invitations_expires_after_created" CHECK ("community_invitations"."expires_at" > "community_invitations"."created_at"),
	CONSTRAINT "community_invitations_max_uses_positive" CHECK ("community_invitations"."max_uses" is null or "community_invitations"."max_uses" >= 1),
	CONSTRAINT "community_invitations_uses_within_limit" CHECK ("community_invitations"."uses" >= 0 and ("community_invitations"."max_uses" is null or "community_invitations"."uses" <= "community_invitations"."max_uses")),
	CONSTRAINT "community_invitations_revoked_after_created" CHECK ("community_invitations"."revoked_at" is null or "community_invitations"."revoked_at" >= "community_invitations"."created_at")
);
