CREATE TABLE "community_members" (
	"id" text PRIMARY KEY NOT NULL,
	"community_id" text NOT NULL,
	"user_id" text NOT NULL,
	"status" text NOT NULL,
	"standing" text DEFAULT 'MEMBER' NOT NULL,
	"source" text NOT NULL,
	"added_by" text,
	"invitation_id" text,
	"joined_at" timestamp with time zone NOT NULL,
	"ended_at" timestamp with time zone,
	"ended_by" text,
	"version" bigint NOT NULL,
	CONSTRAINT "community_members_stint_key" UNIQUE("id","community_id","user_id"),
	CONSTRAINT "community_members_status_valid" CHECK ("community_members"."status" in ('ACTIVE', 'LEFT', 'REMOVED')),
	CONSTRAINT "community_members_standing_valid" CHECK ("community_members"."standing" in ('OWNER', 'MEMBER')),
	CONSTRAINT "community_members_source_valid" CHECK ("community_members"."source" in ('ADDED', 'INVITATION')),
	CONSTRAINT "community_members_version_positive" CHECK ("community_members"."version" > 0),
	CONSTRAINT "community_members_ended_consistent" CHECK (("community_members"."status" = 'ACTIVE') = ("community_members"."ended_at" is null)),
	CONSTRAINT "community_members_ended_after_joined" CHECK ("community_members"."ended_at" is null or "community_members"."ended_at" >= "community_members"."joined_at"),
	CONSTRAINT "community_members_source_consistent" CHECK (("community_members"."source" = 'INVITATION') = ("community_members"."invitation_id" is not null)),
	CONSTRAINT "community_members_owner_active" CHECK ("community_members"."standing" <> 'OWNER' or "community_members"."status" = 'ACTIVE'),
	CONSTRAINT "community_members_left_by_self" CHECK ("community_members"."status" <> 'LEFT' or "community_members"."ended_by" = "community_members"."user_id")
);
